      text: '{\n    "$schema": "http://json-schema.org/draft-06/schema#",\n    "$id": "urn:OCPP:Cp:2:2025:1:ClearTariffsResponse",\n    "comment": "OCPP 2.1 Edition 1 (c) OCA, Creative Commons Attribution-NoDerivatives 4.0 International Public License",\n    "definitions": {\n        "TariffClearStatusEnumType": {\n            "javaType": "TariffClearStatusEnum",\n            "type": "string",\n            "additionalProperties": false,\n            "enum": [\n                "Accepted",\n                "Rejected",\n                "NoTariff"\n            ]\n        },\n        "ClearTariffsResultType": {\n            "javaType": "ClearTariffsResult",\n            "type": "object",\n            "additionalProperties": false,\n            "properties": {\n                "statusInfo": {\n                    "$ref": "#/definitions/StatusInfoType"\n                },\n                "tariffId": {\n                    "description": "Id of tariff for which _status_ is reported. If no tariffs were found, then this field is absent, and _status_ will be `NoTariff`.\\r\\n",\n                    "type": "string",\n                    "maxLength": 60\n                },\n                "status": {\n                    "$ref": "#/definitions/TariffClearStatusEnumType"\n                },\n                "customData": {\n                    "$ref": "#/definitions/CustomDataType"\n                }\n            },\n            "required": [\n                "status"\n            ]\n        },\n        "StatusInfoType": {\n            "description": "Element providing more information about the status.\\r\\n",\n            "javaType": "StatusInfo",\n            "type": "object",\n            "additionalProperties": false,\n            "properties": {\n                "reasonCode": {\n                    "description": "A predefined code for the reason why the status is returned in this response. The string is case-insensitive.\\r\\n",\n                    "type": "string",\n                    "maxLength": 20\n                },\n                "additionalInfo": {\n                    "description": "Additional text to provide detailed information.\\r\\n",\n                    "type": "string",\n                    "maxLength": 1024\n                },\n                "customData": {\n                    "$ref": "#/definitions/CustomDataType"\n                }\n            },\n            "required": [\n                "reasonCode"\n            ]\n        },\n        "CustomDataType": {\n            "description": "This class does not get \'AdditionalProperties = false\' in the schema generation, so it can be extended with arbitrary JSON properties to allow adding custom data.",\n            "javaType": "CustomData",\n            "type": "object",\n            "properties": {\n                "vendorId": {\n                    "type": "string",\n                    "maxLength": 255\n                }\n            },\n            "required": [\n                "vendorId"\n            ]\n        }\n    },\n    "type": "object",\n    "additionalProperties": false,\n    "properties": {\n        "clearTariffsResult": {\n            "type": "array",\n            "additionalItems": false,\n            "items": {\n                "$ref": "#/definitions/ClearTariffsResultType"\n            },\n            "minItems": 1\n        },\n        "customData": {\n            "$ref": "#/definitions/CustomDataType"\n        }\n    },\n    "required": [\n        "clearTariffsResult"\n    ]\n}',
