      fileName: "FirmwareStatusNotificationRequest.json",
      text: '{\n    "$schema": "http://json-schema.org/draft-06/schema#",\n    "$id": "urn:OCPP:Cp:2:2025:1:FirmwareStatusNotificationRequest",\n    "comment": "OCPP 2.1 Edition 1 (c) OCA, Creative Commons Attribution-NoDerivatives 4.0 International Public License",\n    "definitions": {\n        "FirmwareStatusEnumType": {\n            "description": "This contains the progress status of the firmware installation.\\r\\n",\n            "javaType": "FirmwareStatusEnum",\n            "type": "string",\n            "additionalProperties": false,\n            "enum": [\n                "Downloaded",\n                "DownloadFailed",\n                "Downloading",\n                "DownloadScheduled",\n                "DownloadPaused",\n                "Idle",\n                "InstallationFailed",\n                "Installing",\n                "Installed",\n                "InstallRebooting",\n                "InstallScheduled",\n                "InstallVerificationFailed",\n                "InvalidSignature",\n                "SignatureVerified"\n            ]\n        },\n        "StatusInfoType": {\n            "description": "Element providing more information about the status.\\r\\n",\n            "javaType": "StatusInfo",\n            "type": "object",\n            "additionalProperties": false,\n            "properties": {\n                "reasonCode": {\n                    "description": "A predefined code for the reason why the status is returned in this response. The string is case-insensitive.\\r\\n",\n                    "type": "string",\n                    "maxLength": 20\n                },\n                "additionalInfo": {\n                    "description": "Additional text to provide detailed information.\\r\\n",\n                    "type": "string",\n                    "maxLength": 1024\n                },\n                "customData": {\n                    "$ref": "#/definitions/CustomDataType"\n                }\n            },\n            "required": [\n                "reasonCode"\n            ]\n        },\n        "CustomDataType": {\n            "description": "This class does not get \'AdditionalProperties = false\' in the schema generation, so it can be extended with arbitrary JSON properties to allow adding custom data.",\n            "javaType": "CustomData",\n            "type": "object",\n            "properties": {\n                "vendorId": {\n                    "type": "string",\n                    "maxLength": 255\n                }\n            },\n            "required": [\n                "vendorId"\n            ]\n        }\n    },\n    "type": "object",\n    "additionalProperties": false,\n    "properties": {\n        "status": {\n            "$ref": "#/definitions/FirmwareStatusEnumType"\n        },\n        "requestId": {\n            "description": "The request id that was provided in the\\r\\nUpdateFirmwareRequest that started this firmware update.\\r\\nThis field is mandatory, unless the message was triggered by a TriggerMessageRequest AND there is no firmware update ongoing.\\r\\n",\n            "type": "integer"\n        },\n        "statusInfo": {\n            "$ref": "#/definitions/StatusInfoType"\n        },\n        "customData": {\n            "$ref": "#/definitions/CustomDataType"\n        }\n    },\n    "required": [\n        "status"\n    ]\n}',
